// 要上傳到 R2 的資料夾（要和 status.json 同一個資料夾）
const FOLDER = '';  // 空白 = 放在 bucket 最外層
// R2 公開網址（目前 GPT 初稿用的網域）
const PUBLIC_BASE = 'https://pub-f84e602f02924e6e8d238fe4ef0f3752.r2.dev';

// 網頁內容（由 Claude 產生，已用 base64 編碼）
const FILES = [
  { name: "preview.html", mime: "text/html", b64: "" },
  { name: "index.html", mime: "text/html", b64: "" },
  { name: "line-qr.png", mime: "image/png", b64: "" },
  { name: "thumb-fb-2230488854054329.jpg", mime: "image/jpeg", b64: "" }
];

return FILES.map(f => ({
  json: (() => { const key = FOLDER ? `${FOLDER}/${f.name}` : f.name; return { key, url: `${PUBLIC_BASE}/${key}` }; })(),
  binary: {
    data: { data: f.b64, mimeType: f.mime || 'text/html', fileName: f.name, fileExtension: f.name.split('.').pop() },
  },
}));

// 逐一核對：實際路徑、網址、能不能打開、內容是不是網頁
return $input.all().map((item, i) => {
  const src = $('準備網頁檔案').all()[i].json;
  const status = item.json.statusCode;
  const body = String(item.json.body ?? item.json.data ?? '');
  const ok = status === 200 && (!src.key.endsWith('.html') || body.toLowerCase().includes('<!doctype html'));
  return { json: {
    結果: ok ? '✅ 成功，可以打開' : `❌ 失敗（HTTP ${status}）`,
    實際路徑: src.key,
    網址: src.url,
    說明: ok ? '' : (status === 404
      ? '找不到檔案：請在 R2 後台確認檔案是否在 ' + src.key + '（不是 bucket 最外層），以及 bucket 是否已開啟公開網址'
      : '請檢查 R2 公開存取設定'),
  }};
});
